import{_ as l,o as i,c as n,a5 as s}from"./chunks/framework.CXroN2RO.js";const u=JSON.parse('{"title":"第18章 デバッグとプロファイリング ── 全レイヤを「見る」技術","description":"","frontmatter":{"title":"第18章 デバッグとプロファイリング ── 全レイヤを「見る」技術","study":{"source":"IT教本","kind":"学習ガイド","status":"学習計画・概要","summary":"ここまでの章で「システムがどう動くか」を学んだ。この章は 「動いている実物を観測する技術」だ。トッププログラマとそれ以外を 分けるのは、書く速度ではなく原因特定の速度である。"}},"headers":[],"relativePath":"guide/low-level/debugging-and-profiling.md","filePath":"guide/low-level/debugging-and-profiling.md"}'),e={name:"guide/low-level/debugging-and-profiling.md"};function o(t,a,r,d,p,g){return i(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="第18章-デバッグとプロファイリング-──-全レイヤを「見る」技術" tabindex="-1">第18章 デバッグとプロファイリング ── 全レイヤを「見る」技術 <a class="header-anchor" href="#第18章-デバッグとプロファイリング-──-全レイヤを「見る」技術" aria-label="Permalink to &quot;第18章 デバッグとプロファイリング ── 全レイヤを「見る」技術&quot;">​</a></h1><h2 id="学ぶ理由" tabindex="-1">学ぶ理由 <a class="header-anchor" href="#学ぶ理由" aria-label="Permalink to &quot;学ぶ理由&quot;">​</a></h2><p>ここまでの章で「システムがどう動くか」を学んだ。この章は 「動いている実物を観測する技術」だ。トッププログラマとそれ以外を 分けるのは、書く速度ではなく<strong>原因特定の速度</strong>である。 そして最適化の鉄則はただ一つ ──「推測するな、計測せよ」。 計測できない人の最適化は迷信であり、AI生成コードのレビュー (最終目標のひとつ)も、検証手段を持つ人だけが本当にできる。</p><h2 id="到達目標" tabindex="-1">到達目標 <a class="header-anchor" href="#到達目標" aria-label="Permalink to &quot;到達目標&quot;">​</a></h2><ul><li>VSデバッガを完全に使いこなせる(条件付きBP、データBP、ダンプ解析、 リリースビルドデバッグ、逆アセンブリ併読)</li><li>クラッシュの4大類型を症状から切り分けられる</li><li>CPUプロファイラ(VS/Tracy/Superluminal/Unreal Insights)で ホットスポットとスパイクを特定できる</li><li>GPUプロファイラ(RenderDoc/PIX)でGPUフレームを分解できる</li><li>「CPUバウンドかGPUバウンドか」から始まる系統的な最適化手順を実践できる</li></ul><h2 id="前提知識" tabindex="-1">前提知識 <a class="header-anchor" href="#前提知識" aria-label="Permalink to &quot;前提知識&quot;">​</a></h2><p>全章(特に第4章アセンブリ、第6章メモリ、第8章スレッド、第11〜13章GPU)。</p><h2 id="学ぶ内容" tabindex="-1">学ぶ内容 <a class="header-anchor" href="#学ぶ内容" aria-label="Permalink to &quot;学ぶ内容&quot;">​</a></h2><ol><li><strong>Visual Studioデバッガ 完全習得</strong><ul><li>ブレークポイント術: 条件付き、ヒットカウント、<strong>データブレーク ポイント(このアドレスに書いたら停止 ── メモリ破壊犯の現行犯逮捕)</strong>、 関数BP、トレースポイント</li><li>ウォッチ/メモリ/レジスタ/逆アセンブリ/並列スタックウィンドウ</li><li>Edit and Continue、Natvis(TArray等を見やすく ── UE標準装備)</li><li><strong>リリースビルドのデバッグ</strong>(最適化との付き合い方、第4章の実戦)</li><li>リモートデバッグ、アタッチ</li></ul></li><li><strong>クラッシュ解析</strong><ul><li>クラッシュ4大類型と初動: (a) Access Violation → アドレスを見る(0近傍=ヌルポ、 0xdd..=解放済み、0xcd..=未初期化 ← 第6章回収) (b) スタックオーバーフロー (c) 純粋仮想呼び出し/vtable破壊 (d) ヒープ破壊(壊れた場所≠壊した場所 → データBP・ASan・PageHeap)</li><li><strong>ミニダンプ解析</strong>: WinDbg/VSでダンプを開き、!analyze、 コールスタック・レジスタから原因推定(QAから来るダンプの読み方)</li><li>シンボル(PDB)の仕組みとシンボルサーバ(第7章の回収)</li><li>assert文化・ログ設計(再現困難バグへの備え)</li></ul></li><li><strong>CPUプロファイリング</strong><ul><li>2方式の理解: <strong>サンプリング</strong>(統計的・全体像)と <strong>インストルメンテーション</strong>(区間計測・スパイク向き)</li><li>VS診断ツール、<strong>Tracy</strong>(ゲーム向き・無料・フレーム軸表示)、 Superluminal、Unreal Insights / Unity Profiler</li><li>読み方: セルフ時間vs包括時間、ホットパス、<strong>平均ではなく 最悪フレーム(スパイク)を見る</strong>(ゲームは99パーセンタイルが体感)</li><li>マルチスレッドの観察: どのコアが遊んでいるか、ロック待ち、 ジョブの隙間(第8章の実戦)</li><li>メモリプロファイリング: リーク検出、確保頻度、断片化</li></ul></li><li><strong>GPUプロファイリングとデバッグ</strong><ul><li><strong>切り分けの第一歩: CPUバウンドかGPUバウンドか</strong> (GPU使用率・stat unit・フレーム時間の挙動で判定)</li><li><strong>RenderDoc</strong>: フレームキャプチャ→イベント順に描画を再生→ ステート検査→ピクセル履歴→シェーダデバッグ。 「絵が出ない/おかしい」系の必須ツール</li><li><strong>PIX on Windows</strong>: GPU時間の計測(オキュパンシ、各パスのms)、 タイムライン ──「どのパスが重いか」系の必須ツール</li><li>GPUバウンドの内訳分解: 頂点/ピクセル/帯域/固定機能 (解像度を下げて速くなればピクセル系、など切り分けヒューリスティクス)</li><li>デバイスロスト/GPUクラッシュ(TDR)、Aftermath/DRED(概要)</li></ul></li><li><strong>系統的最適化プロセス(この章の総まとめ)</strong><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 計測して現状把握(フレーム時間分布・スパイク頻度)</span></span>
<span class="line"><span>2. CPU / GPU どちらがボトルネックか</span></span>
<span class="line"><span>3. その中のどのシステム/パスか(プロファイラ)</span></span>
<span class="line"><span>4. なぜ遅いか(アルゴリズム? キャッシュ? 同期待ち? 帯域?)</span></span>
<span class="line"><span>5. 仮説→修正→再計測(1つずつ! 同時に2つ変えない)</span></span></code></pre></div><ul><li>最適化の優先順位: アルゴリズム/データ構造 → データレイアウト → 並列化 → マイクロ最適化(この順で費用対効果が高い)</li></ul></li><li><strong>AIコードレビューへの応用(最終目標の回収)</strong><ul><li>AI生成コードの典型的問題パターン集: 毎フレーム確保、隠れたコピー(値渡しstring/vector)、O(n²)、 スレッド安全性の欠如、例外前提設計、キャッシュ敵対的レイアウト、 「動くが計測していない」最適化</li><li>レビュー手順: 正しさ(UB・境界・所有権)→ 性能(計測)→ 設計(依存方向)</li></ul></li></ol><h2 id="重要概念" tabindex="-1">重要概念 <a class="header-anchor" href="#重要概念" aria-label="Permalink to &quot;重要概念&quot;">​</a></h2><ul><li><strong>推測するな、計測せよ</strong> ── 本章の、そして最適化のすべて</li><li><strong>データブレークポイント</strong> ── メモリ破壊バグの最終兵器</li><li><strong>平均でなく最悪フレーム</strong> ── ゲーム特有の品質基準</li><li><strong>ボトルネックの階層的切り分け</strong>(CPU/GPU→システム→原因)</li><li><strong>観測手段を持つ者だけが「理解した」と言える</strong></li></ul><h2 id="ゲーム開発との関係" tabindex="-1">ゲーム開発との関係 <a class="header-anchor" href="#ゲーム開発との関係" aria-label="Permalink to &quot;ゲーム開発との関係&quot;">​</a></h2><p>この章は「関係」ではなく日常業務そのもの。QAのクラッシュレポート対応、 最適化週間、絵が出ないバグ、フレーム落ち調査 ── 全部この章である。</p><h2 id="演習" tabindex="-1">演習 <a class="header-anchor" href="#演習" aria-label="Permalink to &quot;演習&quot;">​</a></h2><ol><li>わざと作ったメモリ破壊バグ(範囲外書き込みで隣の変数を壊す)を、 データブレークポイントで犯人特定せよ。</li><li>クラッシュするプログラムのミニダンプを自動保存する仕組み (SetUnhandledExceptionFilter+MiniDumpWriteDump)を自作ゲームに 組み込み、ダンプをWinDbg/VSで開いて原因を特定せよ。</li><li>第15章の自作エンジンに<strong>Tracy</strong>を組み込み、ゾーンマーカーで フレーム内訳を可視化せよ。意図的なスパイク(たまにsleep)を仕込み、 プロファイラで発見する練習をせよ。</li><li>自作エンジンの敵1万体シーンで最適化プロセスを一周せよ: 計測→ボトルネック特定→仮説→修正→再計測をレポートにまとめる。</li><li>RenderDocで「テクスチャが真っ黒になるバグ」(自分で仕込む: サンプラ設定ミス等)を特定せよ。ピクセル履歴を使うこと。</li><li>PIXで自作/サンプルD3D12アプリのGPUタイムラインを取り、 最も重いパスを特定→解像度スケールで仮説検証せよ。</li><li>AIに「パーティクルシステムを書いて」と頼み、生成コードを 本章のレビュー手順で査読し、問題点を列挙→計測で裏取りせよ。</li></ol><h2 id="おすすめ書籍" tabindex="-1">おすすめ書籍 <a class="header-anchor" href="#おすすめ書籍" aria-label="Permalink to &quot;おすすめ書籍&quot;">​</a></h2><ul><li>『Debug Hacks』── Linux寄りだが思想が良い</li><li>John Robbins &quot;Debugging Applications for Microsoft .NET and Microsoft Windows&quot; ── Windowsデバッグの古典</li><li>『Windowsデバッグの極意』── WinDbg/ダンプ解析の和書</li><li>&quot;The Art of Debugging&quot; / 各プロファイラ公式ドキュメント (Tracyのマニュアルは特に良質)</li></ul><h2 id="おすすめoss" tabindex="-1">おすすめOSS <a class="header-anchor" href="#おすすめoss" aria-label="Permalink to &quot;おすすめOSS&quot;">​</a></h2><ul><li><strong>Tracy</strong>(wolfpld/tracy)── 組み込んで学ぶ。ソースも読む価値大</li><li><strong>RenderDoc</strong>(baldurk/renderdoc)</li><li><strong>microprofile / optick</strong> ── ゲーム向けプロファイラの実装を読む</li><li>Google sanitizers(ASan/TSan/UBSan)── VS/Clangから使う</li></ul><h2 id="おすすめ動画" tabindex="-1">おすすめ動画 <a class="header-anchor" href="#おすすめ動画" aria-label="Permalink to &quot;おすすめ動画&quot;">​</a></h2><ul><li>CppCon (Chandler Carruth) &quot;Going Nowhere Faster&quot; 等ベンチマーク系講演</li><li>GDC最適化講演(各スタジオのポストモーテム)</li><li>PIX/RenderDoc公式チュートリアル動画</li><li>Handmade Heroのデバッグ回(Caseyのデバッガ操作は芸術)</li></ul><h2 id="読むべきソースコード" tabindex="-1">読むべきソースコード <a class="header-anchor" href="#読むべきソースコード" aria-label="Permalink to &quot;読むべきソースコード&quot;">​</a></h2><ul><li>Tracyのクライアント部(計測はどう実装されているか)</li><li>UE5 <code>Core/Private/ProfilingDebugging/</code>(スタッツシステムの実装)</li><li>crashpad / breakpad(クラッシュレポートの産業実装)</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>データブレークポイントはどんなバグに使うか。通常のBPとの違いは?</li><li>Access Violationのアドレスが 0x0000000C / 0xDDDDDDDD / ランダム のとき、それぞれ何を疑うか。</li><li>サンプリングとインストルメンテーションの得失は?</li><li>「平均60fpsなのに体感が悪い」とき何を見るか。</li><li>CPUバウンドかGPUバウンドかをどう判定するか(2つ以上の方法で)。</li><li>「解像度を下げても速くならないGPUバウンド」は何が疑われるか。</li><li>最適化で「同時に2つ変えてはいけない」のはなぜか。</li></ol><hr><h2 id="この章がゲームのどこで使われているか" tabindex="-1">この章がゲームのどこで使われているか <a class="header-anchor" href="#この章がゲームのどこで使われているか" aria-label="Permalink to &quot;この章がゲームのどこで使われているか&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>開発サイクル全体を覆う「観測層」</span></span>
<span class="line"><span>────────────────────────────────────────────────</span></span>
<span class="line"><span>        [ゲーム本体(第1〜17章の全部)]</span></span>
<span class="line"><span>              ▲          ▲          ▲</span></span>
<span class="line"><span>   VSデバッガ │   Tracy/Insights │   RenderDoc/PIX</span></span>
<span class="line"><span>   (CPU実行を │   (フレーム時間を │   (GPUフレームを</span></span>
<span class="line"><span>    命令単位で見る)  区間単位で見る)    ドロー単位で見る)</span></span>
<span class="line"><span>────────────────────────────────────────────────</span></span>
<span class="line"><span>クラッシュ→ダンプ→WinDbg / スパイク→プロファイラ / 絵バグ→RenderDoc</span></span>
<span class="line"><span>「ボタンから画面まで」の全区間に観測ポイントを置けるのがこの章の力</span></span></code></pre></div>`,28)])])}const h=l(e,[["render",o]]);export{u as __pageData,h as default};
